{
  "investigate": [
    {
      "tool": "sql",
      "query": "SELECT i.order_id, i.amount, i.vat, i.total FROM invoices i JOIN ledger l ON i.order_id = l.order_id WHERE ABS(l.total - (l.amount + l.vat)) > 0.01 OR ABS(l.vat - (l.amount * 0.15)) > 0.01 LIMIT 5;",
      "why": "Compare the invoice table with the ledger violations to determine if the error originates in invoice extraction (invoice-agent) or during sync (sync-job)."
    }
  ],
  "hypotheses": [
    {
      "service": "invoice-agent",
      "kind": "bad_deploy",
      "mechanism": "The deploy of invoice-agent v1.1.1 at t=465 introduced a fault in invoice extraction, causing incorrect VAT (e.g., 15x amount instead of 15%) or total calculations, which sync-job faithfully copies to the ledger.",
      "supporting": ["E10", "E3", "E1", "E23"],
      "refuting": ["E24"],
      "explains": ["I3_ledger_integrity"],
      "repair_plan": [
        {"action": "rollback_service", "params": {"service": "invoice-agent"}},
        {"action": "resync_ledger", "params": {}}
      ]
    }
  ],
  "summary": "A bad deploy of invoice-agent likely caused systematic invoice calculation errors, propagating to the ledger."
}
